import React from 'react';

function WeekView({ date, entries }) {
  const getWeekDays = () => {
    const week = [];
    const current = new Date(date);
    const day = current.getDay() || 7;
    current.setDate(current.getDate() - day + 1);

    for (let i = 0; i < 7; i++) {
      week.push(new Date(current));
      current.setDate(current.getDate() + 1);
    }

    return week;
  };

  const weekDays = getWeekDays();
  const dayNames = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
  const monthNames = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

  const getDayEntries = (date) => {
    const dateKey = date.toDateString();
    const dayEntry = entries[dateKey];

    if (!dayEntry) return [];

    return [
      ...(dayEntry.morning || []).map(item => ({ ...item, timeBlock: 'Утро' })),
      ...(dayEntry.day || []).map(item => ({ ...item, timeBlock: 'День' })),
      ...(dayEntry.evening || []).map(item => ({ ...item, timeBlock: 'Вечер' }))
    ];
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Yoga': '#9b59b6',
      'Boxing': '#e74c3c',
      'SoftDev': '#3498db',
      'MBA': '#2ecc71',
      'English': '#f1c40f',
      'Oratory': '#e67e22',
      'Math': '#1abc9c',
      'Chinise': '#e84393',
      'Finance': '#27ae60',
      'Chess': '#8e44ad',
      'Business': '#d35400'
    };
    return colors[category] || '#95a5a6';
  };

  const formatDate = (date) => {
    return `${date.getDate()} ${monthNames[date.getMonth()]}`;
  };

  const isToday = (date) => {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  };

  return (
    <div className="week-view">
      <h2>
        Неделя {formatDate(weekDays[0])} - {formatDate(weekDays[6])}
      </h2>

      <div className="week-grid">
        {weekDays.map((day, index) => {
          const dayEntries = getDayEntries(day);
          const isCurrentDay = isToday(day);

          return (
            <div key={index} className={`week-day-column ${isCurrentDay ? 'today' : ''}`}>
              <div className="week-day-header">
                <span className="day-name">{dayNames[index]}</span>
                <span className="day-number">{day.getDate()}</span>
              </div>

              <div className="week-day-entries">
                {dayEntries.length > 0 ? (
                  dayEntries.map((entry, i) => (
                    <div
                      key={i}
                      className="week-entry"
                      style={{ borderLeftColor: getCategoryColor(entry.category) }}
                    >
                      <div className="week-entry-header">
                        <span className="time-block-badge">{entry.timeBlock}</span>
                        <span className="category">{entry.category}</span>
                      </div>
                      <div className="week-entry-details">
                        <span className="subcategory">{entry.subcategory}</span>
                        <span className="time">⏱️ {entry.time}</span>
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="no-entries">Нет записей</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default WeekView;
